    Match name against pattern using fnmatch.fnmatchcase semantics.
    Supports *, ?, [abc], [a-z], [!abc].
    A ] immediately after [ or [! is a literal.
    An unterminated [ is a literal [.
    Match is anchored to the whole string.
    """
    def match_here(pat, pat_idx, name, name_idx):
        # pat_idx: current index in pattern
        # name_idx: current index in name
        while pat_idx < len(pat) and name_idx < len(name):
            c = pat[pat_idx]
            if c == '*':
                # Consume consecutive *
                while pat_idx < len(pat) and pat[pat_idx] == '*':
                    pat_idx += 1
                # If pattern is exhausted, match if name is exhausted
                if pat_idx == len(pat):
                    return name_idx == len(name)
                # Try matching rest of pattern at each position in name
                for i in range(name_idx, len(name) + 1):
                    if match_here(pat, pat_idx, name, i):
                        return True
                return False
            elif c == '?':
                # Matches exactly one character
                pat_idx += 1
                name_idx += 1
            elif c == '[':
                # Parse character class
                # Check for negation
                negated = False
                idx = pat_idx + 1
                if idx < len(pat) and pat[idx] == '!':
                    negated = True
                    idx += 1
                # Check if ] is immediately after [ or [!
                if idx < len(pat) and pat[idx] == ']':
                    # Literal ]
                    # The ] is a literal character, so we need to match it
                    if name[name_idx] != ']':
                        return False
                    pat_idx = idx + 1
                    name_idx += 1
                else:
                    # Parse the character class until closing ]
                    # Find the closing ]
                    end_idx = idx
                    while end_idx < len(pat) and pat[end_idx] != ']':
                        end_idx += 1
                    if end_idx >= len(pat):
                        # Unterminated [ - treat [ as literal
                        if name[name_idx] != '[':
                            return False
                        pat_idx += 1
                        name_idx += 1
                    else:
                        # Parse the range expressions between idx and end_idx
                        content = pat[idx:end_idx]
                        matched_char = False
                        i = 0
                        while i < len(content):
                            ch = content[i]
                            if i + 2 < len(content) and content[i + 1] == '-':
                                # Range
                                start_ch = ch
                                end_ch = content[i + 2]
                                if start_ch <= name[name_idx] <= end_ch:
                                    matched_char = True
                                    break
                                i += 3
                            else:
                                if name[name_idx] == ch:
                                    matched_char = True
                                    break
                                i += 1
                        if negated:
                            if matched_char:
                                return False
                        else:
                            if not matched_char:
                                return False
                        pat_idx = end_idx + 1
                        name_idx += 1
            else:
                # Literal character
                if c != name[name_idx]:
                    return False
                pat_idx += 1
                name_idx += 1
        # Both should be exhausted
        # Handle remaining * in pattern
        while pat_idx < len(pat) and pat[pat_idx] == '*':
            pat_idx += 1
        return pat_idx == len(pat) and name_idx == len(name)

    return match_here(pattern, 0, name, 0)
