def glob_match(pattern, name):
    """
    Match a name against a glob pattern with fnmatch.fnmatchcase semantics.

    Supports:
    - * : matches any run of characters (including empty)
    - ? : matches exactly one character
    - [seq] : matches any single character in seq
    - [!seq] : matches any single character not in seq
    - A ] immediately after [ or [! is treated as a literal ]
    - An unterminated [ is treated as a literal [

    The match is anchored to the whole string.
    """
    def _match(pattern, name):
        # Recursive helper with backtracking
        # pattern: str, name: str
        # Returns True if pattern matches name entirely

        # Base cases
        if not pattern:
            return not name
        if not name:
            # Pattern must be empty to match, or consist only of * characters
            for ch in pattern:
                if ch != '*':
                    return False
            return True

        p = pattern[0]

        if p == '*':
            # Skip consecutive *
            i = 0
            while i < len(pattern) and pattern[i] == '*':
                i += 1
            rest_pattern = pattern[i:]
            # Try matching rest_pattern against name[j:] for j from 0 to len(name)
            for j in range(len(name) + 1):
                if _match(rest_pattern, name[j:]):
                    return True
            return False

        elif p == '?':
            # Matches exactly one character
            return _match(pattern[1:], name[1:])

        elif p == '[':
            # Parse the character class
            # Find the closing ]
            # A ] immediately after [ or [! is literal
            i = 1
            negated = False
            if i < len(pattern) and pattern[i] == '!':
                negated = True
                i += 1
            # Check if ] is immediately after [ or [!
            if i < len(pattern) and pattern[i] == ']':
                # ] is literal, so we need to find the next ]
                i += 1
            # Now find the closing ]
            close_idx = -1
            j = i
            while j < len(pattern):
                if pattern[j] == ']':
                    close_idx = j
                    break
                j += 1

            if close_idx == -1:
                # Unterminated [, treat [ as literal
                if name[0] == '[':
                    return _match(pattern[1:], name[1:])
                else:
                    return False

            # Extract the content between [ and ]
            content = pattern[i:close_idx]
            next_pattern = pattern[close_idx + 1:]

            # Parse the content into a set of characters to match
            # Support ranges like a-z
            matched = False
            ch = name[0]
            k = 0
            while k < len(content):
                if k + 2 < len(content) and content[k+1] == '-':
                    # Range
                    start_char = content[k]
                    end_char = content[k+2]
                    if start_char <= ch <= end_char:
                        matched = True
                        break
                    k += 3
                else:
                    if ch == content[k]:
                        matched = True
                        break
                    k += 1

            if negated:
                matched = not matched

            if matched:
                return _match(next_pattern, name[1:])
            else:
                return False

        else:
            # Literal character
            if name[0] == p:
                return _match(pattern[1:], name[1:])
            else:
                return False

    return _match(pattern, name)
